def calculate_total(prices, discount_percent):
    """Суммирует цены заказа и применяет скидку в процентах.

    discount_percent задаётся в процентах и допустим в диапазоне от 0 до 100
    включительно. Любые другие значения (в том числе нечисловые, NaN и
    бесконечности) приводят к ValueError.
    """
    subtotal = sum(prices)

    is_number = isinstance(discount_percent, (int, float)) and not isinstance(
        discount_percent, bool
    )
    if not is_number or not math.isfinite(discount_percent):
        raise ValueError("discount_percent must be a finite number")
    if not 0 <= discount_percent <= 100:
        raise ValueError("discount_percent must be between 0 and 100 inclusive")

    return subtotal * (1 - discount_percent / 100)
